const x=$json;
const required=['event_type','conversation_id','channel'];
for(const k of required) if(typeof x[k]!=='string'||!x[k].trim()) throw new Error(`audit_missing_${k}`);
if(!['facebook','whatsapp','instagram','internal'].includes(x.channel))
 throw new Error('audit_invalid_channel');
if(x.metadata && typeof x.metadata!=='object') throw new Error('audit_invalid_metadata');
return [{json:{...x,event_id:x.event_id||`evt_${Date.now()}_${Math.random().toString(36).slice(2,10)}`,
timestamp:x.timestamp||new Date().toISOString()}}];

const x=JSON.parse(JSON.stringify($json));
const forbidden=/api[_-]?key|access[_-]?token|refresh[_-]?token|authorization|password|passwd|otp|pin|cvv|card[_-]?number|pan|consumer[_-]?secret|client[_-]?secret|cart[_-]?token|nonce|webhook[_-]?secret/i;

function scrub(v){
  if(Array.isArray(v)) return v.map(scrub);
  if(v && typeof v==='object'){
    const o={};
    for(const [k,val] of Object.entries(v)){
      if(forbidden.test(k)) o[k]='[REDACTED]';
      else o[k]=scrub(val);
    }
    return o;
  }
  if(typeof v==='string'){
    // Defense-in-depth for common secret-like values embedded in strings.
    if(forbidden.test(v) && v.length>80) return '[REDACTED]';
    return v;
  }
  return v;
}
const y=scrub(x);
// Avoid unnecessary PII in general analytics. Keep customer_id as a
// pseudonymous internal reference; do not store phone/address/name here.
if(y.metadata){
  for(const k of ['phone','phone_e164','address','address_text','email','name','display_name','full_name'])
    if(k in y.metadata) delete y.metadata[k];
}
return [{json:{...y,redaction_applied:true}}];

const x=$json;
const t=x.event_type.toLowerCase();
let category='system';
if(t.includes('security')||t.includes('injection')||t.includes('auth')) category='security';
else if(t.includes('order')||t.includes('transaction')||t.includes('checkout')) category='commerce';
else if(t.includes('cart')||t.includes('coupon')||t.includes('promotion')) category='commerce';
else if(t.includes('customer')||t.includes('identity')) category='identity';
else if(t.includes('kb')||t.includes('retrieval')) category='knowledge';
else if(t.includes('error')||t.includes('failure')||x.success===false) category='reliability';
return [{json:{...x,event_category:category}}];
